-- 真实豆单。保留旧豆 ID，历史订单快照不变；推荐以用户最终汇总表为准。
ALTER TABLE beans ADD COLUMN metadata_json TEXT NOT NULL DEFAULT '{}';
-- 旧的自定义豆子没有甜度、余韵数据，以 0 表示未记录。
UPDATE beans SET scales_json=json_array(json_extract(scales_json,'$[0]'),0,json_extract(scales_json,'$[1]'),json_extract(scales_json,'$[2]'),0) WHERE json_array_length(scales_json)=3;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('blend','Gemilai 意式拼配','巴西、中国、乌干达','','中深烘焙','["黑巧克力","烤坚果","麦芽糖"]','[1,2,3,5,3]','','','','','1','{"process":"水洗、日晒","altitude":"","series":"意式拼配豆","category":"经典醇香","recommended":["拿铁"],"predicted":false}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
