INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('blue','牙买加蓝山 1 号','牙买加，克利夫顿庄园','','中度烘焙','["焦糖","坚果","蜂蜜奶油","红色浆果"]','[2,4,2,4,4]','','','','','1','{"process":"水洗","altitude":"","series":"蓝山咖啡","category":"温润均衡","recommended":["手冲","Dirty"],"predicted":false}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('afu','埃塞俄比亚 · 阿福','埃塞俄比亚，罕贝拉阿姆福','74158','中浅烘焙','["水蜜桃","西柚","菠萝","果酒"]','[4,5,1,3,5]','','预计具有鲜明的热带水果香气，伴随发酵带来的酒香。酸甜表现突出，余韵较长。','','','1','{"process":"72 小时暗房厌氧日晒","altitude":"2072m","series":"埃塞俄比亚精品咖啡","category":"果香馥郁","recommended":["手冲","拿铁"],"predicted":true}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('peru-sl09','秘鲁 · 和平之角庄园 SL-09','秘鲁，和平之角庄园','SL-09','中浅烘焙','["花香","莓果","香草","蜜糖"]','[3,4,1,3,4]','','预计以花香与蜜糖甜感为主，伴随适度莓果酸质，整体柔和清爽。','','包装标注的品种为 SL-09，未直接标注瑰夏品种，暂按分类归入瑰夏系列。','1','{"process":"传统水洗","altitude":"1700m","series":"瑰夏系列","category":"清甜花香","recommended":["手冲","Dirty","拿铁"],"predicted":true}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('panama-geisha','巴拿马 · 帕洛玛尔-坎特拉庄园瑰夏','巴拿马，帕洛玛尔-坎特拉庄园','瑰夏','中浅烘焙','["白色花香","柠檬草","苹果","佛手柑"]','[4,4,1,2,5]','','预计呈现较为明亮的柑橘酸质与白色花香，茶感清透，层次细腻，余韵悠长。','','','1','{"process":"水洗","altitude":"1750m","series":"瑰夏系列","category":"清甜花香","recommended":["手冲","Dirty","拿铁"],"predicted":true}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('geisha','埃塞俄比亚 · 瑰夏村红标','埃塞俄比亚，瑰夏村','戈里瑰夏（Gori Gesha）','中浅烘焙','["桃花","黑布林","莓果","佛手柑"]','[4,4,1,3,5]','','预计具有浓郁的核果与莓果香气，结合细腻花香。日晒处理可能赋予其更丰富的果甜和较长的余韵。','','','1','{"process":"日晒","altitude":"1926–2011m","series":"瑰夏系列","category":"果香馥郁","recommended":["手冲","Dirty","拿铁"],"predicted":true}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
INSERT INTO beans (id,name,origin,variety,roast,tags_json,scales_json,front,body,finish,note,available,metadata_json) VALUES ('colombia-geisha','哥伦比亚 · 微风庄园瑰夏','哥伦比亚，微风庄园','瑰夏','中浅烘焙','["柠檬草","香茅","柑橘","杏桃"]','[4,4,1,3,4]','','预计以柑橘与杏桃的酸甜感为主，伴随清新的草本香气，整体具有鲜明的水果调性。','','','1','{"process":"厌氧水洗","altitude":"1730m","series":"瑰夏系列","category":"清新明亮","recommended":["手冲","Dirty","拿铁"],"predicted":true}') ON CONFLICT(id) DO UPDATE SET name=excluded.name,origin=excluded.origin,variety=excluded.variety,roast=excluded.roast,tags_json=excluded.tags_json,scales_json=excluded.scales_json,front=excluded.front,body=excluded.body,finish=excluded.finish,note=excluded.note,available=excluded.available,metadata_json=excluded.metadata_json;
